package br.com.confirmacao.professional.domain; import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity @Table(name="professionals",uniqueConstraints={@UniqueConstraint(name="uk_professionals_email",columnNames="email"),@UniqueConstraint(name="uk_professionals_registration",columnNames="registration_number")}) public class Professional{@Id private UUID id;@Column(name="full_name",nullable=false,length=150)private String fullName;@Column(nullable=false,length=254)private String email;@Column(length=30)private String phone;@Column(name="registration_number",length=50)private String registrationNumber;@Column(nullable=false)private boolean active;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected Professional(){}public Professional(String n,String e,String p,String r){id=UUID.randomUUID();fullName=name(n);email=email(e);phone=blank(p);registrationNumber=blank(r);active=true;createdAt=updatedAt=Instant.now();}public void update(String n,String e,String p,String r){fullName=name(n);email=email(e);phone=blank(p);registrationNumber=blank(r);updatedAt=Instant.now();}private String name(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("O nome do profissional é obrigatório");return v.trim();}private String email(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("O e-mail do profissional é obrigatório");return v.trim().toLowerCase(Locale.ROOT);}private String blank(String v){return v==null||v.isBlank()?null:v.trim();}public void activate(){active=true;updatedAt=Instant.now();}public void deactivate(){active=false;updatedAt=Instant.now();}public UUID getId(){return id;}public String getFullName(){return fullName;}public String getEmail(){return email;}public String getPhone(){return phone;}public String getRegistrationNumber(){return registrationNumber;}public boolean isActive(){return active;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
